function OUT = AF7R58ZZP_ONEFILE_EARLY_INTERVENTION_INSTALL()
% AF7R58ZZP
% EARLY-INTERVENTION architecture phase 1.
%
% This installer is EXACT-BYTE source-bound. It does NOT patch production
% with fragile textual anchors.  It:
%   1) requires the exact AF7R58ZZN-R2 production SHA,
%   2) reconstructs the fully reviewed candidate source from an embedded
%      gzip/base64 payload,
%   3) verifies the candidate SHA and source invariants,
%   4) parses the entire candidate class BEFORE production write,
%   5) backs up production,
%   6) writes exact candidate bytes and verifies post SHA,
%   7) rolls back on any post-write failure.
%
% ARCHITECTURE INSTALLED
%   - ordinary H-second trigger is unchanged and remains fail-safe authority.
%   - an EARLY scheduler runs when:
%       (a) sensor-known obstacle set changes, or
%       (b) active-reference version changes.
%   - early preview horizon comes ONLY from the live theorem field
%       sensor_horizon_certificate.first_collision_lead_LB_s
%     capped by finite reference-domain remaining time and quantized DOWN to dt.
%   - early preview uses ONLY the sensor-known active mask.
%   - no unseen obstacle becomes generator input.
%   - extended reference preview is prepared sensor-independently BEFORE the
%     hard sensor-dependent clock, with rolling one-endpoint update when valid.
%   - early deadline retries reuse the latched early collision event instead
%     of rebuilding the extended preview every 25 ms.
%   - a non-deadline early failure does NOT suppress the ordinary H-second
%     trigger later.
%
% IMPORTANT
%   This is phase 1 of the architecture split.  The current MATLAB generator
%   is still synchronous, so the existing fixed 4-ms commit guard is retained
%   temporarily.  It is NOT used as an avoidance-timing target.  Phase 2 moves
%   planning/certification to a separate worker/process; then the artificial
%   fixed 4-ms planner deadline can be replaced by the physical/theoretical
%   deadline while activation remains deliberately early.

PRE_SHA='4b72f2667086282cd1f7609a1555c84f0245ddbfaf650604c4b768886a886234';
POST_SHA='d8861e3e8a0333835ce35dd1ba06b36d56d2fd7e1ed6960637f78d23008aac76';

OUT=struct('schema','AF7R58ZZP_EARLY_INTERVENTION_V1', ...
    'production_modified',false,'rollback_performed',false, ...
    'status','OPEN','error',struct());

pR=which('REPLANNING_SYSTEM');
assert(~isempty(pR)&&isfile(pR), ...
    '[AF7R58ZZP] REPLANNING_SYSTEM unresolved.');
root=fileparts(pR);

outdir=tempname(root);
[ok,msg]=mkdir(outdir);
assert(ok,'%s',msg);

report=fullfile(outdir,'AF7R58ZZP_REPORT.txt');
matp=fullfile(outdir,'AF7R58ZZP_OUT.mat');
backup=fullfile(outdir,'REPLANNING_SYSTEM_PRE_AF7R58ZZP.m');

fid=fopen(report,'wt','n','UTF-8');
assert(fid>=0);
cf=onCleanup(@()safe_fclose(fid)); %#ok<NASGU>

say(fid,'====================================================================================================');
say(fid,' AF7R58ZZP | EARLY-INTERVENTION ARCHITECTURE PHASE 1');
say(fid,'====================================================================================================');
say(fid,'[AUTHORITY] exactByteReplacement=1 | parseBeforeWrite=1 | rollbackOnFailure=1');
say(fid,'[EARLY] firstKnownOrVersionChange=1 | theoremDerivedPreview=1 | lastMomentThreshold=0');
say(fid,'[SAFETY] ordinaryHorizonTriggerRetained=1 | acceptanceChanged=0 | certificateMathChanged=0');
say(fid,'[SENSING] detectedOnlyGenerator=1 | earlyKernelUsesKnownMaskOnly=1 | unseenTruthPreplan=0');
say(fid,'[DEADLINE] fixed4msTemporarilyRetained=1 | fixed4msAsSchedulingTarget=0');

writeStarted=false;

try
    pre=file_hash(pR);
    OUT.pre_sha=pre;
    OUT.production_path=pR;

    say(fid,'');
    say(fid,'[A. EXACT CURRENT SOURCE]');
    say(fid,' path = %s',pR);
    say(fid,' SHA  = %s',pre);

