'iR4vPOBlB+lF+8/eILEGk2UhDw/n6w19nA4Jo4KBWJPFmVaXkjfs5RPREsDNpQ+0pNZy6lwmwBFmqAUz1Dq3WG6lzA8/YP6OxxFYb22cLxaeAJnNz9M+Hgp8' ...
'bmrm83PrpydaGwZ9oCKIfVEogkKq9fBmaK40Jr860SqnN2r1zedn+6xZ9kkKqH7WhhHEAEAMOIiBD2IwDgjo+2yNg6j5IGpJIFKgerqNvilodZDsKTpwX58C' ...
'mbecPslO/xySmP48J/d+OSDUUtknP9ingQwy6w9liA5CiD7LER1kRnQQRnQgIDrzSBGtmSGFEY6pj24tM7q1MLo1Ad3T2dD1vozZFWgcoZ8zi4Vi6jJnxw/d' ...
'k6aUpOOHK8X1/I3Jkp5WA48g3s/05Q3D4o1PWuHNoW3dLI85YGMOpKf7KOpMRVPcgB14Dhp27UpvC0MCcbUBDWCqCqXEwZQCMBdpJDkUHNxUIDMcyIwCSK+V' ...
'jshpDuO0AgZORBaV14uSezr8Av/+H5eeROeDDwoA'
    };
    enc=[B64{:}];
    gzBytes=matlab.net.base64decode(enc);

    stageDir=fullfile(outdir,'STAGE');
    [ok,msg]=mkdir(stageDir);
    assert(ok,'%s',msg);

    gzPath=fullfile(stageDir,'REPLANNING_SYSTEM.m.gz');
    fg=fopen(gzPath,'wb');
    assert(fg>=0,'[AF7R58ZZP] cannot create staged gzip.');
    fwrite(fg,uint8(gzBytes),'uint8');
    fclose(fg);

    gunzip(gzPath,stageDir);
    staged=fullfile(stageDir,'REPLANNING_SYSTEM.m');
    assert(isfile(staged),'[AF7R58ZZP] candidate decompression failed.');

    stageSHA=file_hash(staged);
    OUT.staged_post_sha=stageSHA;
    assert(strcmp(stageSHA,POST_SHA), ...
        '[AF7R58ZZP] embedded candidate SHA mismatch.');

    S=read_utf8_binary(staged);

    % ------------------------------------------------------------------
    % Static architecture/safety audit BEFORE production write.
    % ------------------------------------------------------------------
    assert(count_exact(S,'AF7R58ZZP theorem-derived EARLY intervention scheduler')==1);
    assert(count_exact(S,'function prepare_early_intervention_reference_cache(obj,t_now)')==1);
    assert(count_exact(S,'early_intervention_trigger(obj,active,t_now)')==1);
    assert(count_exact(S,'obj.trigger_core(active,pL_ref,q_ref,time.t);')==1);
    assert(count_exact(S,'hard_modify_deadline_s      = 4.0e-3;')==1);

    assert(contains(S,'sensor_horizon_certificate.first_collision_lead_LB_s') || ...
        contains(S,'C.first_collision_lead_LB_s'));
    assert(contains(S,'Hraw=min(Hproof,tend-t_now);'));
    assert(contains(S,'nstep=floor(Hraw/dt);'));
    assert(contains(S,'double(known));');

    % Finite-sensing invariants.
    assert(contains(S,'The generator receives ONLY sensor-known obstacles:'));
    assert(contains(S,'''detected_only_obstacle_contract'',true'));
    assert(contains(S,'Initial known set is empty.'));
    assert(contains(S,'raw_sensor_gate alone may admit a previously unknown obstacle.'));

    % Existing ordinary trigger/deadline fail-fast authority remains.
    assert(count_exact(S,'REFERENCE_ONLY_DEADLINE_AFTER_RESOURCE_MODEL')==1);
    assert(count_exact(S,'REFERENCE_ONLY_DEADLINE_AFTER_REUSE_GATE')==1);
    assert(count_exact(S,'REFERENCE_ONLY_COMMIT_PREPARATION_DEADLINE_EXCEEDED')==1);
    assert(count_exact(S,'REFERENCE_ONLY_DEADLINE_AFTER_EVAL_HANDLES')==1);
    assert(count_exact(S,'REFERENCE_ONLY_DEADLINE_AFTER_CERT_METADATA')==1);
    assert(count_exact(S,'REFERENCE_ONLY_DEADLINE_AFTER_ROLLBACK_SNAPSHOT')==1);
    assert(contains(S,'finished after the hard online modification deadline.'));

    % Critical ordering theorem for the implementation:
    % extended reference work is sensor-independent and precedes hard clock;
    % sensor gate then ordinary trigger then early scheduler.
    pPrep=strfind(S,'obj.prepare_early_intervention_reference_cache(double(time.t));');
    pHard=strfind(S,'t_hard_cycle=tic;');
    pSensor=strfind(S,'obj.raw_sensor_gate(pQ_cur,obj.static_obstacle_map);');
    pOrd=strfind(S,'obj.trigger_core(active,pL_ref,q_ref,time.t);');
    pEarly=strfind(S,'obj.early_intervention_trigger(active,double(time.t));');
    assert(numel(pPrep)==1&&numel(pHard)==1&&numel(pSensor)==1&& ...
        numel(pOrd)==1&&numel(pEarly)==1&& ...
        pPrep<pHard&&pHard<pSensor&&pSensor<pOrd&&pOrd<pEarly, ...
        '[AF7R58ZZP] early-scheduler execution ordering is not closed.');

    % The early scheduler never requests a new extended computation unless
    % known set/reference version changed; deadline retry reuses the pending
    % event instead.
    assert(contains(S,'if ~(knownChanged || versionChanged)'));
    assert(contains(S,'if pendingValid && ~knownChanged && ~versionChanged'));

    % A non-deadline early failure must re-arm ordinary trigger identity.
    assert(contains(S, ...
        'A non-deadline early attempt is a completed'));
    assert(contains(S,'obj.replan_request_active=false;'));

    % ------------------------------------------------------------------
    % Parse the ENTIRE candidate class before first production write.
    % ------------------------------------------------------------------
    parseDir=fullfile(outdir,'PARSE');
    [ok,msg]=mkdir(parseDir);
    assert(ok,'%s',msg);

    parseName='AF7R58ZZP_PARSE_REPLANNING_SYSTEM';
    parseText=strrep(S,'classdef REPLANNING_SYSTEM < handle', ...
        ['classdef ' parseName ' < handle']);
    assert(~strcmp(parseText,S), ...
        '[AF7R58ZZP] temporary class rename failed.');

    parsePath=fullfile(parseDir,[parseName '.m']);
    write_utf8_binary(parsePath,parseText);
    addpath(parseDir,'-begin');
    cp=onCleanup(@()safe_rmpath(parseDir)); %#ok<NASGU>
    eval(['clear ' parseName]);
    mc=meta.class.fromName(parseName);
    assert(~isempty(mc),'[AF7R58ZZP] full candidate class parse failed.');
    eval(['clear ' parseName]);

    say(fid,'');
    say(fid,'[B. PREFLIGHT BEFORE PRODUCTION WRITE]');
    say(fid,' exact pre-source SHA                     = 1');
    say(fid,' exact embedded candidate SHA             = 1');
    say(fid,' full candidate class parse               = 1');
    say(fid,' ordinary H trigger retained              = 1');
    say(fid,' early scheduler waits for last moment    = 0');
    say(fid,' early preview source = first_collision_lead_LB_s');
    say(fid,' early preview quantized DOWN by dt       = 1');
    say(fid,' extended packet prepared before hard clock= 1');
    say(fid,' early kernel receives known mask only    = 1');
    say(fid,' finite sensing contract retained         = 1');
    say(fid,' fixed 4-ms scheduling target             = 0');
    say(fid,' fixed 4-ms synchronous guard retained    = 1');
    say(fid,' production writes                        = 0');

    % ------------------------------------------------------------------
    % Transactional exact-byte install.
    % ------------------------------------------------------------------
    copyfile(pR,backup,'f');
    OUT.backup_path=backup;

    writeStarted=true;
    copyfile(staged,pR,'f');
    OUT.production_modified=true;

    post=file_hash(pR);
    OUT.post_sha=post;
    assert(strcmp(post,POST_SHA), ...
        '[AF7R58ZZP] production post-write SHA mismatch.');

    say(fid,'');
    say(fid,'[C. INSTALL RESULT]');
    say(fid,' post SHA                              = %s',post);
    say(fid,' exact staged/post identity             = 1');
    say(fid,' ordinary safety trigger changed        = 0');
    say(fid,' continuous certificate math changed    = 0');
    say(fid,' generator/MEX math changed             = 0');
    say(fid,' finite sensing changed                 = 0');
    say(fid,' 4-ms property changed                  = 0');
    say(fid,' early intervention scheduler installed = 1');

    OUT.status='EARLY_INTERVENTION_PHASE1_INSTALLED__CLEAN_RERUN_REQUIRED';

catch ME
    OUT.error=struct('identifier',ME.identifier, ...
        'message',ME.message,'stack',{ME.stack});

    if writeStarted && isfile(backup)
        try
            copyfile(backup,pR,'f');
            OUT.rollback_performed=true;
            OUT.production_modified=false;
        catch
        end
    end

    OUT.status='INSTALL_FAILED__ROLLBACK_ATTEMPTED';

    say(fid,'');
    say(fid,'[INSTALL FAILURE]');
    say(fid,' identifier = %s',ME.identifier);
    say(fid,' message    = %s',ME.message);
    say(fid,' rollback   = %d',OUT.rollback_performed);
end

OUT.report_path=report;
OUT.mat_path=matp;
save(matp,'OUT','-v7');

say(fid,'');
say(fid,'RETURN: %s',report);
say(fid,'RETURN: %s',matp);
say(fid,'status = %s',OUT.status);

assignin('base','AF7R58ZZP_OUT',OUT);
end


function n=count_exact(s,pat)
n=numel(strfind(s,pat));
end


function s=read_utf8_binary(path)
fid=fopen(path,'rb');
assert(fid>=0);
c=onCleanup(@()fclose(fid)); %#ok<NASGU>
b=fread(fid,'*uint8');
s=native2unicode(b.','UTF-8');
end


function write_utf8_binary(path,s)
b=unicode2native(s,'UTF-8');
fid=fopen(path,'wb');
assert(fid>=0);
c=onCleanup(@()fclose(fid)); %#ok<NASGU>
fwrite(fid,uint8(b),'uint8');
end


function h=file_hash(path)
md=java.security.MessageDigest.getInstance('SHA-256');
fid=fopen(path,'rb');
assert(fid>=0);
c=onCleanup(@()fclose(fid)); %#ok<NASGU>
while true
    b=fread(fid,1024*1024,'*uint8');
    if isempty(b), break; end
    md.update(b);
end
u=typecast(md.digest(),'uint8');
h=lower(reshape(dec2hex(u,2).',1,[]));
end


function say(fid,varargin)
fprintf(fid,[varargin{1} '\n'],varargin{2:end});
fprintf([varargin{1} '\n'],varargin{2:end});
end


function safe_rmpath(p)
try
    rmpath(p);
catch
end
end


function safe_fclose(fid)
try
    fclose(fid);
catch
end
end
